const { getE2ERepoRoot } = require("./repoRoot.cjs");
const { test, expect } = require("@playwright/test");
const { _electron: electron } = require("playwright");
const fs = require("fs");
const os = require("os");
const path = require("path");

/** Short path for Verify UI workflow_dispatch `e2e_focus=offline-kill-smoke` (runner vs heavy suite isolation). */
test.setTimeout(120000);

test("Verify UI smoke: Electron shell reaches top status bar", async () => {
    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), "neuralshell-e2e-verify-ui-smoke-"));
    const app = await electron.launch({
        args: ["."],
        cwd: getE2ERepoRoot(),
        env: {
            ...process.env,
            NEURAL_USER_DATA_DIR: userDataDir,
            NEURAL_IGNORE_INTEGRITY: "1",
        },
    });

    try {
        const page = await app.firstWindow();
        await page.waitForLoadState("domcontentloaded");
        const onboardingProgressJson = JSON.stringify({
            provider_sweep: true,
            vault_save: true,
            run_proof: true,
            share_badge: true,
        });
        await page.addInitScript((progressJson) => {
            try {
                globalThis.localStorage.setItem("neuralshell_onboarding_dismissed_v1", "1");
                globalThis.localStorage.setItem("neuralshell_setup_complete_v1", "1");
                globalThis.localStorage.setItem("neuralshell_first_boot_completed_v1", "1");
                globalThis.localStorage.setItem("neuralshell_first_boot_dismissed_v1", "1");
                globalThis.localStorage.setItem("neuralshell_welcome_overlay_dismissed_v1", "1");
                globalThis.localStorage.setItem("neuralshell_onboarding_progress_v1", progressJson);
            } catch {
                /* ignore */
            }
        }, onboardingProgressJson);
        await page.reload({ waitUntil: "domcontentloaded" });
        await expect(page.getByTestId("top-status-bar")).toBeVisible({ timeout: 90000 });
    } finally {
        await app.close();
        try {
            fs.rmSync(userDataDir, { recursive: true, force: true });
        } catch {
            /* best effort */
        }
    }
});

